/// The logic of a trigger id.
#[must_use]
pub fn logic(trigger_id: i32) -> Option<&'static Logic> {
    LOGICS
        .binary_search_by_key(&trigger_id, |l| l.trigger_id)
        .ok()
        .map(|i| &LOGICS[i])
}
